import{DATASET_KEY,normalize,formatMoney,formatPercent,escapeHtml,makeId,loadContext,saveSetting,saveSales,saleSalary,initPageState,applyTheme,enableDialogBackdropClose,showFatal}from"./core.js";
import{parseCommissionWorkbook}from"./commission.js";
applyTheme();
const $=id=>document.getElementById(id);let ctx=null,state={search:"",category:"all",focusOnly:true},visible=[],raf=0,scrollRestored=false;
const xlsxReady=new Promise((resolve,reject)=>{if(globalThis.XLSX){resolve();return}const script=document.querySelector('script[src$="xlsx.full.min.js"]');if(!script){reject(Error("Модуль импорта недоступен."));return}script.addEventListener("load",resolve,{once:true});script.addEventListener("error",()=>reject(Error("Не удалось загрузить модуль импорта.")),{once:true})});
const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
function headerKey(v){return String(v??"").trim().toLowerCase().replaceAll("ё","е").replace(/\s+/g," ")}
function find(headers,parts){return headers.findIndex(h=>parts.every(p=>h.includes(p)))}
function rate(v){if(typeof v==="number"&&Number.isFinite(v))return v>1?v/100:v;const n=Number(String(v??"").replace("%","").replace(",","."));return Number.isFinite(n)?(n>1?n/100:n):null}
function parseWorkbook(buffer){if(!globalThis.XLSX)throw Error("Модуль импорта ещё загружается. Повторите попытку.");return parseCommissionWorkbook(buffer,{strict:true}).rows}
function categories(){const list=[...new Set(ctx.products.map(p=>p.subcategory).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"ru"));$("categorySelect").innerHTML='<option value="all">Все категории</option>'+list.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join("");$("categorySelect").value=state.category}
function articleLabel(p){const parts=[];if(p.sulpakArticle)parts.push(`S:${p.sulpakArticle}`);if(p.mechtaArticle)parts.push(`M:${p.mechtaArticle}`);return parts.join(" ")||p.article}
function filtered(){const q=normalize(state.search);if(q)return ctx.products.filter(p=>{const commission=ctx.relation.get(p.article),models=Array.isArray(p.modelKeys)?p.modelKeys.join(" "):"";return normalize(`${p.article} ${p.sulpakArticle||""} ${p.mechtaArticle||""} ${p.title} ${p.originalTitle} ${p.commCode} ${commission?.commCode||""} ${models} ${p.brand}`).includes(q)});return ctx.products.filter(p=>(!state.focusOnly||ctx.relation.has(p.article))&&(state.category==="all"||p.subcategory===state.category))}
function card(p){const c=ctx.relation.get(p.article),rates=c?`<div class="rates"><div class="rate"><span>Ниже 100%</span><b>${formatPercent(c.belowPlan)}</b></div><div class="rate"><span>При 100%</span><b>${formatPercent(c.atPlan)}</b></div></div>`:`<div class="rates"><div class="rate"><span>Комиссия</span><b>Без комиссии</b></div></div>`;return`<article class="card"><div class="product-photo"><img loading="lazy" src="${escapeHtml(p.photoUrl)}" alt=""><span class="article">${escapeHtml(articleLabel(p))}</span></div><div class="card-body"><p class="category">${escapeHtml(p.subcategory||p.category)}</p><h2>${escapeHtml(p.title)}</h2><p class="model">${escapeHtml(c?.commCode||p.commCode||p.brand)}</p>${rates}<button class="add-sale" data-article="${p.article}">Добавить продажу</button></div></article>`}
function gridMetrics(){const w=innerWidth,size=document.documentElement.dataset.size||"medium",cols=w<=720?(size==="large"?1:2):w<=1050?(size==="small"?4:size==="large"?2:3):(size==="small"?5:size==="large"?3:4),base=w<=390?380:w<=720?405:455,rowHeight=Math.round(base*(size==="small"?.82:size==="large"?1.2:1));return{cols,rowHeight}}
function renderWindow(){raf=0;const grid=$("grid");if(!visible.length){grid.innerHTML="";$("emptyState").hidden=false;return}const {cols,rowHeight}=gridMetrics(),gridTop=grid.getBoundingClientRect().top+scrollY,firstRow=Math.max(0,Math.floor((scrollY-gridTop)/rowHeight)-3),lastRow=Math.min(Math.ceil(visible.length/cols),Math.ceil((scrollY+innerHeight-gridTop)/rowHeight)+4),start=firstRow*cols,end=Math.min(visible.length,lastRow*cols),top=firstRow*rowHeight,bottom=Math.max(0,(Math.ceil(visible.length/cols)-lastRow)*rowHeight);grid.innerHTML=`<div class="virtual-spacer" style="height:${top}px"></div>${visible.slice(start,end).map(card).join("")}<div class="virtual-spacer" style="height:${bottom}px"></div>`}
function queueWindow(){if(!raf)raf=requestAnimationFrame(renderWindow)}
function render(){visible=filtered();$("emptyState").hidden=!!visible.length;$("visibleCount").textContent=visible.length;$("matchedCount").textContent=ctx.relation.size;$("fileStatus").textContent="Данные загружены";renderWindow();if(!scrollRestored){scrollRestored=true;requestAnimationFrame(()=>requestAnimationFrame(()=>{scrollTo({top:Number(state.scrollY)||0,behavior:"auto"});renderWindow()}))}}
function commissionFor(p){return ctx.relation.get(p.article)||{commCode:p.commCode||p.article,belowPlan:0,atPlan:0}}
function openSale(article){const p=ctx.products.find(x=>x.article===article);if(!p)return;const c=commissionFor(p);ctx.active=p;$("saleProductImage").src=p.photoUrl;$("saleProductArticle").textContent=`Артикул ${articleLabel(p)}`;$("saleProductTitle").textContent=p.title;$("saleDate").value=today();$("salePrice").value="";$("saleQuantity").value=1;$("saleBelowRate").textContent=c.belowPlan?formatPercent(c.belowPlan):"Без комиссии";$("saleError").textContent="";preview();$("saleDialog").showModal()}
function preview(){if(!ctx?.active)return;const c=commissionFor(ctx.active);$("saleSalaryPreview").textContent=formatMoney(Number($("salePrice").value)*Number($("saleQuantity").value)*c.belowPlan)}
function toast(t){$("toast").textContent=t;$("toast").classList.add("show");setTimeout(()=>$("toast").classList.remove("show"),2400)}
function makeSale(p,c,price,quantity,date){c=c||commissionFor(p);const createdAt=new Date().toISOString(),soldAt=new Date(`${date}T12:00:00`).toISOString();return{id:makeId(),article:p.article,title:p.title,category:p.subcategory||p.category,commCode:c.commCode,price,quantity,planMode:"below",rate:c.belowPlan,belowRate:c.belowPlan,atPlanRate:c.atPlan,soldAt,createdAt,updatedAt:createdAt,returned:false}}
function registerTools(){const m=document.modelContext;if(!m?.registerTool)return;const controller=new AbortController;m.registerTool({name:"create_sale",title:"Добавить продажу",description:"Добавляет продажу и сохраняет её локально. Для товара без ставки комиссия равна нулю.",inputSchema:{type:"object",properties:{article:{type:"string"},price:{type:"number",exclusiveMinimum:0},quantity:{type:"integer",minimum:1},date:{type:"string",format:"date"}},required:["article","price","quantity","date"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(i){const p=ctx.products.find(x=>x.article===String(i.article));if(!p)throw Error("Товар не найден.");const c=commissionFor(p);if(!(i.price>0)||!Number.isInteger(i.quantity)||i.quantity<1||!/^\d{4}-\d{2}-\d{2}$/.test(i.date))throw Error("Некорректные данные продажи.");const s=makeSale(p,c,i.price,i.quantity,i.date);ctx.sales.push(s);await saveSales(ctx.sales);return{id:s.id,salary:saleSalary(s)}}},{signal:controller.signal})}
async function init(){initPageState("catalog",()=>state,s=>{state={...state,...s}});ctx=await loadContext();categories();$("searchInput").value=state.search;$("focusOnly").checked=state.focusOnly;render();$("searchInput").oninput=e=>{state.search=e.target.value;render()};$("categorySelect").onchange=e=>{state.category=e.target.value;render()};$("focusOnly").onchange=e=>{state.focusOnly=e.target.checked;render()};$("grid").onclick=e=>{const b=e.target.closest("[data-article]");if(b)openSale(b.dataset.article)};addEventListener("scroll",queueWindow,{passive:true});addEventListener("resize",queueWindow,{passive:true});$("importButton").onclick=()=>{$("importSummary").hidden=true;$("importDialog").showModal()};$("chooseFileButton").onclick=()=>$("fileInput").click();$("fileInput").onchange=async()=>{const file=$("fileInput").files?.[0];if(!file)return;$("importSummary").hidden=false;$("importSummary").textContent="Читаю файл…";try{const buffer=await file.arrayBuffer(),rows=parseWorkbook(buffer),dataset={fileName:file.name,importedAt:new Date().toISOString(),rows,rawWorkbook:buffer};await saveSetting(DATASET_KEY,dataset);ctx=await loadContext();render();$("importSummary").innerHTML=`Строк: <b>${rows.length}</b> · связано: <b>${ctx.relation.size}</b> · без артикула: <b>${ctx.unmatched.length}</b>`}catch(err){$("importSummary").textContent=err.message}$("fileInput").value=""};$("closeSaleDialog").onclick=$("cancelSaleButton").onclick=()=>$("saleDialog").close();$("saleForm").oninput=preview;$("saleForm").onsubmit=async e=>{e.preventDefault();const p=ctx.active,c=ctx.relation.get(p.article),price=Number($("salePrice").value),quantity=Number($("saleQuantity").value),date=$("saleDate").value;if(!(price>0)||!Number.isInteger(quantity)||quantity<1||!date){$("saleError").textContent="Проверьте дату, цену и количество.";return}const sale=makeSale(p,c,price,quantity,date);ctx.sales.push(sale);await saveSales(ctx.sales);$("saleDialog").close();toast(`Начислено ${formatMoney(saleSalary(sale))}`)}}
$("fileInput").accept=".xlsx";enableDialogBackdropClose($("saleDialog"),$("importDialog"));init().then(registerTools).catch(showFatal);if("serviceWorker"in navigator)addEventListener("load",()=>navigator.serviceWorker.register("./sw.js"));
const photoViewer=document.createElement("div");photoViewer.className="photo-viewer";photoViewer.innerHTML='<button type="button" aria-label="Закрыть">×</button><img alt="Увеличенное фото товара">';document.body.append(photoViewer);const viewerImage=photoViewer.querySelector("img"),closePhoto=()=>{photoViewer.classList.remove("open");setTimeout(()=>{if(!photoViewer.classList.contains("open"))viewerImage.removeAttribute("src")},260)},openPhoto=(src,alt)=>{viewerImage.src=src;viewerImage.alt=alt||"Фото товара";photoViewer.classList.add("open")};photoViewer.onclick=e=>{if(e.target===photoViewer||e.target===viewerImage||e.target.closest("button"))closePhoto()};$("grid").addEventListener("click",e=>{const img=e.target.closest(".product-photo img");if(!img)return;e.preventDefault();e.stopPropagation();openPhoto(img.currentSrc||img.src,img.alt)},{capture:true});addEventListener("keydown",e=>{if(e.key==="Escape"&&photoViewer.classList.contains("open"))closePhoto()});
$("searchInput").addEventListener("input",()=>requestAnimationFrame(()=>{scrollTo({top:Math.max(0,$("grid").offsetTop-150),behavior:"auto"});renderWindow()}));
$("chooseFileButton").addEventListener("click",async e=>{if(globalThis.XLSX)return;e.preventDefault();e.stopImmediatePropagation();try{await xlsxReady;$("fileInput").click()}catch(err){$("importSummary").hidden=false;$("importSummary").textContent=err.message}},{capture:true});
const catalogControls=document.querySelector(".catalog-controls"),catalogSearch=document.querySelector(".catalog-controls .search");function syncControlsTransparency(){if(!catalogControls)return;const searchFocused=!!catalogSearch?.contains(document.activeElement);catalogControls.classList.toggle("is-scrolled",scrollY>24&&!searchFocused)}addEventListener("scroll",syncControlsTransparency,{passive:true});catalogSearch?.addEventListener("focusin",syncControlsTransparency);catalogSearch?.addEventListener("focusout",()=>requestAnimationFrame(syncControlsTransparency));requestAnimationFrame(syncControlsTransparency);
